import { useState, useEffect, useRef, useCallback } from "react";

// ── TRACKS DATA ──────────────────────────────────────────────────────────────
const TRACKS = {
  track1: { src: "/Audio/japanese.mp3",   genre: "Japanese / Pop",          label: "♪ HARU - YORUSHIKA" },
  track2: { src: "/Audio/cyberpunk.mp3",  genre: "Cyberpunk / Synth",       label: "♪ I REALLY WANT TO STAY AT YOUR HOUSE" },
  track3: { src: "/Audio/chill.mp3",      genre: "Chill / Ambient",         label: "♪ CHILL MODE" },
  track4: { src: "/Audio/dystopian.mp3",  genre: "Dystopian / Dark",        label: "♪ DYSTOPIAN MODE" },
  track5: { src: "/Audio/life.mp3",       genre: "Life / Sentimental",      label: "♪ I HAVE NO ENEMIES MODE" },
  track6: { src: "/Audio/reggaestep.mp3", genre: "ReggaeStep / Dub",        label: "♪ MAKE IT BUN DEM" },
  track7: { src: "/Audio/eurobeat.mp3",   genre: "Eurobeat / Racing",       label: "♪ GAS GAS GAS!" },
  track8: { src: "/Audio/phonk.mp3",      genre: "Phonk / Drift",           label: "♪ PHONK MODE" },
  track9: { src: "/Audio/rock.mp3",       genre: "Cyber Rock / Alternative",label: "♪ WHO'S READY FOR TOMORROW" },
};

const MUSIC_LABELS = ["Japanese","Cyberpunk","Chill","Dystopian","Life","ReggaeStep","Eurobeat","Phonk","Cyber Rock"];

// ── PAGES ────────────────────────────────────────────────────────────────────
const PAGES = ["HOME","ABOUT ME","ACHIEVEMENTS","EXPERIENCES"];

// ── CLOCK ────────────────────────────────────────────────────────────────────
function useClock() {
  const [time, setTime] = useState({ hms: "00:00:00", date: "MON, JAN 01 2026" });
  useEffect(() => {
    const tick = () => {
      const now = new Date(new Date().toLocaleString("en-US", { timeZone: "Asia/Manila" }));
      const hh = String(now.getHours()).padStart(2,"0");
      const mm = String(now.getMinutes()).padStart(2,"0");
      const ss = String(now.getSeconds()).padStart(2,"0");
      const days   = ["SUN","MON","TUE","WED","THU","FRI","SAT"];
      const months = ["JAN","FEB","MAR","APR","MAY","JUN","JUL","AUG","SEP","OCT","NOV","DEC"];
      setTime({
        hms: `${hh}:${mm}:${ss}`,
        date: `${days[now.getDay()]}, ${months[now.getMonth()]} ${String(now.getDate()).padStart(2,"0")} ${now.getFullYear()}`
      });
    };
    tick();
    const id = setInterval(tick, 1000);
    return () => clearInterval(id);
  }, []);
  return time;
}

// ── TYPEWRITER ───────────────────────────────────────────────────────────────
function TypeWriter({ text, speed = 55 }) {
  const [displayed, setDisplayed] = useState("");
  useEffect(() => {
    setDisplayed("");
    let i = 0;
    const id = setInterval(() => {
      setDisplayed(text.slice(0, ++i));
      if (i >= text.length) clearInterval(id);
    }, speed);
    return () => clearInterval(id);
  }, [text, speed]);
  return <>{displayed}</>;
}

// ── SCROLL REVEAL ─────────────────────────────────────────────────────────────
function RevealSection({ children, style }) {
  const ref = useRef();
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const obs = new IntersectionObserver(([e]) => { if (e.isIntersecting) setVisible(true); }, { threshold: 0.1 });
    if (ref.current) obs.observe(ref.current);
    return () => obs.disconnect();
  }, []);
  return (
    <section
      ref={ref}
      style={{
        opacity: visible ? 1 : 0,
        transform: visible ? "translateY(0)" : "translateY(30px)",
        transition: "opacity 0.5s ease, transform 0.5s ease",
        ...style
      }}
    >
      {children}
    </section>
  );
}

// ── COUNTER ───────────────────────────────────────────────────────────────────
function Counter({ target }) {
  const [val, setVal] = useState(0);
  const ref = useRef();
  useEffect(() => {
    const obs = new IntersectionObserver(([e]) => {
      if (e.isIntersecting) {
        let cur = 0;
        const step = target / (1200 / 16);
        const id = setInterval(() => {
          cur += step;
          if (cur >= target) { setVal(target); clearInterval(id); return; }
          setVal(Math.floor(cur));
        }, 16);
      }
    }, { threshold: 0.5 });
    if (ref.current) obs.observe(ref.current);
    return () => obs.disconnect();
  }, [target]);
  return <span ref={ref}>{val}</span>;
}

// ── MAIN APP ──────────────────────────────────────────────────────────────────
export default function App() {
  const clock = useClock();
  const [page, setPage] = useState("HOME");
  const [booted, setBooted] = useState(false);
  const [bootDone, setBootDone] = useState(false);
  const [bootProgress, setBootProgress] = useState(0);
  const [bootLines, setBootLines] = useState([]);

  // Audio state
  const audioRef = useRef(null);
  const [currentTrack, setCurrentTrack] = useState(null);
  const [isMuted, setIsMuted] = useState(false);
  const [volume, setVolume] = useState(40);
  const lastVolumeRef = useRef(0.4);

  // Toast badge
  const [badge, setBadge] = useState({ text: "", visible: false });
  const badgeTimer = useRef();

  // Profile zoom
  const [zoom, setZoom] = useState(1.0);

  // Genre label
  const [genreLabel, setGenreLabel] = useState("◈ SELECT A TRACK ◈");

  // ── BOOT SEQUENCE ──────────────────────────────────────────────────────────
  useEffect(() => {
    const alreadyBooted = sessionStorage.getItem("cp_booted");
    if (alreadyBooted) { setBooted(true); setBootDone(true); return; }
    sessionStorage.setItem("cp_booted", "1");

    const msgs = [
      "> Initializing ABANADOR OS v2.0.77...",
      "> Loading cyberpunk core modules...",
      "> Calibrating neural interface...",
      "> Syncing Philippine Standard Time...",
      "> Decrypting portfolio data...",
      "> Welcome, Netrunner.",
    ];
    let i = 0;
    const printLine = () => {
      if (i >= msgs.length) {
        setBootProgress(100);
        setTimeout(() => { setBooted(true); setTimeout(() => setBootDone(true), 600); }, 400);
        return;
      }
      setBootLines(prev => [...prev, msgs[i]]);
      setBootProgress(Math.round(((i + 1) / msgs.length) * 100));
      i++;
      setTimeout(printLine, 320 + Math.random() * 200);
    };
    setTimeout(printLine, 200);
  }, []);

  // ── BODY GLITCH ────────────────────────────────────────────────────────────
  const [glitch, setGlitch] = useState(false);
  useEffect(() => {
    const trigger = () => {
      setGlitch(true);
      setTimeout(() => setGlitch(false), 120);
      setTimeout(trigger, 3000 + Math.random() * 7000);
    };
    const id = setTimeout(trigger, 3000 + Math.random() * 7000);
    return () => clearTimeout(id);
  }, []);

  // ── CURSOR TRAIL ───────────────────────────────────────────────────────────
  const trailRef = useRef([]);
  const mousePos = useRef({ x: 0, y: 0 });
  useEffect(() => {
    // Create trail dots
    const dots = [];
    for (let i = 0; i < 10; i++) {
      const el = document.createElement("div");
      el.style.cssText = `
        position:fixed; width:${10 - i * 0.7}px; height:${10 - i * 0.7}px;
        border-radius:50%; background:#00f5ff; pointer-events:none; z-index:99998;
        transform:translate(-50%,-50%); mix-blend-mode:screen;
        box-shadow:0 0 6px #00f5ff; opacity:${(1 - i / 10) * 0.7};
        left:-100px; top:-100px;
      `;
      document.body.appendChild(el);
      dots.push({ el, x: 0, y: 0 });
    }
    trailRef.current = dots;

    const onMove = e => { mousePos.current = { x: e.clientX, y: e.clientY }; };
    document.addEventListener("mousemove", onMove);

    let raf;
    const animate = () => {
      let px = mousePos.current.x, py = mousePos.current.y;
      dots.forEach((t, i) => {
        t.x += (px - t.x) * (0.35 - i * 0.025);
        t.y += (py - t.y) * (0.35 - i * 0.025);
        t.el.style.left = t.x + "px";
        t.el.style.top  = t.y + "px";
        px = t.x; py = t.y;
      });
      raf = requestAnimationFrame(animate);
    };
    animate();

    return () => {
      document.removeEventListener("mousemove", onMove);
      cancelAnimationFrame(raf);
      dots.forEach(d => d.el.remove());
    };
  }, []);

  // ── AUDIO ENGINE ───────────────────────────────────────────────────────────
  const showBadge = useCallback((text) => {
    setBadge({ text, visible: true });
    clearTimeout(badgeTimer.current);
    badgeTimer.current = setTimeout(() => setBadge(b => ({ ...b, visible: false })), 2800);
  }, []);

  const fadeAudio = useCallback((from, to, duration, cb) => {
    const audio = audioRef.current;
    if (!audio) return;
    const steps = 40, interval = duration / steps, delta = (to - from) / steps;
    let cur = from, count = 0;
    const id = setInterval(() => {
      cur += delta; count++;
      audio.volume = Math.min(1, Math.max(0, cur));
      if (count >= steps) { clearInterval(id); if (cb) cb(); }
    }, interval);
  }, []);

  const switchTrack = useCallback((val) => {
    const track = TRACKS[val];
    if (!track) return;
    const audio = audioRef.current;
    if (!audio) return;

    const doSwitch = () => {
      setCurrentTrack(val);
      audio.src = track.src;
      audio.load();
      audio.currentTime = 0;
      if (!isMuted) {
        audio.volume = 0;
        audio.play().then(() => fadeAudio(0, lastVolumeRef.current, 800)).catch(() => showBadge("⚠ Click anywhere to enable audio"));
      }
      setGenreLabel("◈ " + track.genre.toUpperCase() + " ◈");
      showBadge(track.label);
    };

    if (currentTrack && audio && !audio.paused) {
      fadeAudio(audio.volume, 0, 600, doSwitch);
    } else {
      doSwitch();
    }
  }, [currentTrack, isMuted, fadeAudio, showBadge]);

  const toggleMute = () => {
    const audio = audioRef.current;
    if (!audio) return;
    if (!isMuted) {
      lastVolumeRef.current = audio.volume > 0 ? audio.volume : lastVolumeRef.current;
      fadeAudio(audio.volume, 0, 400, () => { audio.muted = true; });
      setIsMuted(true);
    } else {
      audio.muted = false;
      if (currentTrack) { audio.play().catch(() => {}); fadeAudio(0, lastVolumeRef.current, 400); }
      setIsMuted(false);
    }
  };

  const handleVolume = (e) => {
    const pct = parseInt(e.target.value);
    setVolume(pct);
    lastVolumeRef.current = pct / 100;
    const audio = audioRef.current;
    if (audio && !isMuted) { audio.volume = pct / 100; audio.muted = false; }
  };

  // ── MUSIC SELECTOR (shared header component) ───────────────────────────────
  const MusicHeader = ({ title }) => (
    <header style={styles.header}>
      {/* Scanline */}
      <div style={styles.scanline} />

      <div style={styles.genreLabel}>{genreLabel}</div>
      <h1 style={styles.h1} data-text={title} className="glitch">{title}</h1>

      {/* Profile */}
      <div style={styles.profileWrap}>
        <img
          src="/Images/Abanador_Image.jpg"
          alt="Angelo Ace Williard"
          style={{ ...styles.profile, transform: `scale(${zoom})` }}
        />
        <div style={styles.zoomControls}>
          <button style={styles.zoomBtn} onClick={() => setZoom(z => Math.min(2.5, z + 0.15))}>＋</button>
          <button style={styles.zoomBtn} onClick={() => setZoom(z => Math.max(0.5, z - 0.15))}>－</button>
          <button style={styles.zoomBtn} onClick={() => setZoom(1.0)}>⟳</button>
        </div>
      </div>

      {/* Music picker */}
      <div style={styles.musicContainer}>
        <p style={styles.musicTitle}>⚡ SELECT BACKGROUND MUSIC</p>
        <div style={styles.musicGrid}>
          {MUSIC_LABELS.map((label, i) => {
            const val = `track${i + 1}`;
            return (
              <label key={val} style={styles.radioLabel}>
                <input type="radio" name="music" value={val} checked={currentTrack === val}
                  onChange={() => { if (currentTrack !== val) switchTrack(val); }}
                  style={{ display: "none" }}
                />
                <span style={{ ...styles.customRadio, ...(currentTrack === val ? styles.customRadioChecked : {}) }} />
                {label}
              </label>
            );
          })}
        </div>
        <div style={styles.volRow}>
          <button style={styles.muteBtn} onClick={toggleMute}>{isMuted ? "🔇" : "🔊"}</button>
          <span style={styles.volLabel}>VOL</span>
          <input type="range" min="0" max="100" value={volume} onChange={handleVolume} style={styles.volSlider} />
          <span style={styles.volDisplay}>{volume}%</span>
        </div>
      </div>

      {/* Nav */}
      <nav style={styles.nav}>
        {PAGES.map(p => (
          <a key={p} href="#" onClick={e => { e.preventDefault(); setPage(p); }}
            style={{ ...styles.navLink, ...(page === p ? styles.navActive : {}) }}>
            {p}
          </a>
        ))}
      </nav>
    </header>
  );

  // ── PAGE: HOME ─────────────────────────────────────────────────────────────
  const HomePage = () => (
    <>
      <MusicHeader title="MY PORTFOLIO" />
      <RevealSection>
        <h2 style={styles.h2}><TypeWriter text="WELCOME, NETRUNNER" /></h2>
        <p>I am <strong>Angelo Ace Williard O. Abanador</strong> — a 3rd year BS Information Technology student, Content Creator, and Aspiring Musician from STI College San Jose Del Monte.</p>
        <p>Navigate through the pages above to explore my story, achievements, and experiences. Select a music track to set the vibe, and let the neon grid guide your journey.</p>
        <div style={styles.quickLinks}>
          {[
            { icon: "👤", label: "ABOUT ME",     page: "ABOUT ME" },
            { icon: "🏆", label: "ACHIEVEMENTS", page: "ACHIEVEMENTS" },
            { icon: "⚙",  label: "EXPERIENCES",  page: "EXPERIENCES" },
          ].map(q => (
            <a key={q.page} href="#" onClick={e => { e.preventDefault(); setPage(q.page); }} style={styles.quickLink}>
              <span style={styles.qcIcon}>{q.icon}</span>
              <span style={styles.qcLabel}>{q.label}</span>
            </a>
          ))}
        </div>
      </RevealSection>
    </>
  );

  // ── PAGE: ABOUT ME ─────────────────────────────────────────────────────────
  const AboutPage = () => (
    <>
      <MusicHeader title="ABOUT ME" />
      <RevealSection>
        <h2 style={styles.h2}><TypeWriter text="WHO I AM" /></h2>
        <p>My name is <strong>Angelo Ace Williard O. Abanador</strong>. I am a 3rd year BS Information Technology student at STI College San Jose Del Monte.</p>
        <p>I am currently learning advanced web development, programming concepts, and cybersecurity fundamentals. I'm also a Content Creator and an Aspiring Musician — blending tech passion with creative expression.</p>
      </RevealSection>
      <RevealSection>
        <h2 style={styles.h2}><TypeWriter text="CHARACTERIZATION" /></h2>
        <p>I am a hardworking and curious student who is deeply interested in technology. I prefer learning through practice and problem-solving rather than memorizing concepts.</p>
        <p>I am experienced in both following commands and stepping up to leadership roles. I believe I have an adaptable sense of humor that fits any working environment — professional when needed, fun when allowed.</p>
        <div style={styles.charTags}>
          {["🧠 Problem Solver","🎮 Gamer","🎸 Musician","📹 Content Creator","💻 Developer","🛡 Ethical Hacker"].map(t => (
            <span key={t} style={styles.tag}>{t}</span>
          ))}
        </div>
      </RevealSection>
      <RevealSection>
        <h2 style={styles.h2}><TypeWriter text="SOCIAL LINKS" /></h2>
        <p><strong>Connect with me across the grid:</strong></p>
        <div style={styles.socials}>
          {[
            { href: "https://www.facebook.com/angelo.abanador.2025", src: "/Images/facebook-icon.png", alt: "Facebook" },
            { href: "https://www.youtube.com/@ARtjooew",             src: "/Images/youtube-icon.png",  alt: "YouTube" },
            { href: "https://www.twitch.tv/rtgewerp",                src: "/Images/twitch-icon.png",   alt: "Twitch" },
            { href: "https://www.tiktok.com/@rtgew_wegtr",           src: "/Images/tiktok-icon.png",   alt: "TikTok" },
          ].map(s => (
            <a key={s.alt} href={s.href} target="_blank" rel="noreferrer">
              <img src={s.src} alt={s.alt} style={styles.socialIcon} />
            </a>
          ))}
        </div>
      </RevealSection>
    </>
  );

  // ── PAGE: ACHIEVEMENTS ─────────────────────────────────────────────────────
  const AchievementsPage = () => (
    <>
      <MusicHeader title="ACHIEVEMENTS" />
      <RevealSection>
        <h2 style={styles.h2}><TypeWriter text="UNLOCKED ACHIEVEMENTS" /></h2>
        <ul style={styles.achieveList}>
          {[
            { icon: "🎓", text: "Graduated STEM strand at STI Senior High School" },
            { icon: "🏅", text: "Passed STI Scholarship" },
            { icon: "💻", text: "Passed basic programming subjects" },
            { icon: "🌐", text: "Created simple HTML projects" },
            { icon: "☕", text: "Created simple Java projects" },
            { icon: "🎮", text: "Created a 2D Hack and Slash Platformer game" },
            { icon: "🔧", text: "Successfully served 10 customers on PC Building" },
            { icon: "📋", text: "Completed academic requirements on time" },
            { icon: "💧", text: "Drinks 1 Gallon of Water Consistently" },
            { icon: "⚔",  text: "Adventure Rank 60 in Genshin Impact" },
          ].map(a => (
            <li key={a.text} style={styles.achieveItem}>
              <span style={styles.achIcon}>{a.icon}</span>{a.text}
            </li>
          ))}
        </ul>
      </RevealSection>
      <RevealSection>
        <h2 style={styles.h2}><TypeWriter text="STAT BOARD" /></h2>
        <div style={styles.statCards}>
          {[
            { target: 60, label: "AR IN GENSHIN" },
            { target: 10, label: "PCS BUILT" },
            { target: 3,  label: "YEARS CODING" },
            { target: 1,  label: "GAME RELEASED" },
          ].map(s => (
            <div key={s.label} style={styles.statCard}>
              <div style={styles.scNum}><Counter target={s.target} /></div>
              <div style={styles.scLabel}>{s.label}</div>
            </div>
          ))}
        </div>
      </RevealSection>
    </>
  );

  // ── PAGE: EXPERIENCES ──────────────────────────────────────────────────────
  const ExperiencesPage = () => (
    <>
      <MusicHeader title="EXPERIENCES" />
      <RevealSection>
        <h2 style={styles.h2}><TypeWriter text="FIELD EXPERIENCE" /></h2>
        <div style={styles.expGrid}>
          {[
            { icon: "📹", title: "Content Creation",   desc: "YouTube & Twitch streaming, video editing, community engagement" },
            { icon: "🌐", title: "Web Development",    desc: "Student projects using HTML, CSS & JavaScript — including this portfolio" },
            { icon: "☕", title: "Java & JFrame",       desc: "Basic programming exercises and JFrame GUI application development" },
            { icon: "🛡", title: "Ethical Hacking",    desc: "EC-COUNCIL Ethical Hacking Courses — cybersecurity fundamentals" },
            { icon: "🎮", title: "Game Development",   desc: "GameMaker Studio 2 — built a 2D Hack & Slash Platformer game from scratch" },
            { icon: "👑", title: "Project Management", desc: "Project Manager for a 3D Game Development Capstone project" },
            { icon: "🤝", title: "Group Academics",    desc: "Group academic activities — leadership and team collaboration" },
            { icon: "🎸", title: "Music",              desc: "Basic Guitar, Kalimba, Drums, and Flute aiming to become a musician" },
          ].map(e => (
            <div key={e.title} style={styles.expCard}>
              <div style={styles.expIcon}>{e.icon}</div>
              <div style={styles.expTitle}>{e.title}</div>
              <div style={styles.expDesc}>{e.desc}</div>
            </div>
          ))}
        </div>
      </RevealSection>
    </>
  );

  // ── RENDER ─────────────────────────────────────────────────────────────────
  return (
    <div style={{ ...styles.body, filter: glitch ? "hue-rotate(30deg) brightness(1.15)" : "none", transform: glitch ? "skewX(0.4deg)" : "none" }}>
      {/* Hidden audio element */}
      <audio ref={audioRef} loop />

      {/* Scanline overlay */}
      <div style={styles.scanlineFixed} />

      {/* Clock widget */}
      <div style={styles.clockWidget}>
        <div style={styles.clockTime}>{clock.hms}</div>
        <div style={styles.clockDate}>{clock.date}</div>
        <div style={styles.clockTz}>PHILIPPINE STANDARD TIME</div>
      </div>

      {/* Toast badge */}
      <div style={{ ...styles.trackBadge, opacity: badge.visible ? 1 : 0 }}>{badge.text}</div>

      {/* Boot splash */}
      {!booted && (
        <div style={{ ...styles.bootSplash }}>
          <div style={styles.bootContent}>
            <div style={styles.bootLogo}>A.B.A.N.A.D.O.R OS v2.0</div>
            {bootLines.map((line, i) => <div key={i} style={styles.bootLine}>{line}</div>)}
            <div style={styles.bootBarWrap}>
              <div style={{ ...styles.bootBar, width: bootProgress + "%" }} />
            </div>
          </div>
        </div>
      )}

      {/* Main content */}
      <div style={{ opacity: bootDone ? 1 : 0, transition: "opacity 0.6s ease" }}>
        {page === "HOME"         && <HomePage />}
        {page === "ABOUT ME"     && <AboutPage />}
        {page === "ACHIEVEMENTS" && <AchievementsPage />}
        {page === "EXPERIENCES"  && <ExperiencesPage />}

        <footer style={styles.footer}>
          <p>
            <b style={styles.footerTitle}>My Portfolio</b><br />
            Angelo Ace Williard O. Abanador<br />
            BS Information Technology – 3rd Year<br />
            STI College San Jose Del Monte<br /><br />
            © 2026 All Rights Reserved
          </p>
        </footer>
      </div>
    </div>
  );
}

// ── STYLES ────────────────────────────────────────────────────────────────────
const C = {
  yellow:  "#ffe600",
  cyan:    "#00f5ff",
  pink:    "#ff2d78",
  purple:  "#b400ff",
  dark:    "#0a0a12",
  panel:   "rgba(10,10,24,0.82)",
  glowY:   "0 0 8px #ffe600, 0 0 20px rgba(255,230,0,0.3)",
  glowC:   "0 0 8px #00f5ff, 0 0 20px rgba(0,245,255,0.3)",
  glowP:   "0 0 8px #ff2d78, 0 0 20px rgba(255,45,120,0.3)",
};

const styles = {
  body: {
    fontFamily: "'Orbitron', Arial, sans-serif",
    margin: 0,
    background: C.dark,
    color: "#cde",
    cursor: "none",
    minHeight: "100vh",
  },
  scanlineFixed: {
    pointerEvents: "none",
    position: "fixed",
    inset: 0,
    zIndex: 9999,
    background: "repeating-linear-gradient(to bottom, transparent 0px, transparent 3px, rgba(0,0,0,0.08) 3px, rgba(0,0,0,0.08) 4px)",
  },
  clockWidget: {
    position: "fixed", top: 18, right: 18, zIndex: 1000,
    background: "rgba(0,0,0,.72)", border: `1px solid ${C.yellow}`,
    borderRadius: 4, padding: "10px 16px", textAlign: "right",
    boxShadow: C.glowY, backdropFilter: "blur(6px)",
  },
  clockTime: { fontFamily: "'Courier New', monospace", fontSize: "1.8rem", color: C.yellow, textShadow: C.glowY, letterSpacing: 3 },
  clockDate: { fontFamily: "Arial, sans-serif", fontSize: ".58rem", color: "#aac", letterSpacing: 1.5, marginTop: 2 },
  clockTz:   { fontSize: ".5rem", color: "#556", letterSpacing: 1, marginTop: 1 },

  trackBadge: {
    position: "fixed", bottom: 30, left: "50%", transform: "translateX(-50%)",
